{
  "name": "实验室设备套接字通信接口",
  "name_en": "Laboratory Device Socket Communication Interface",
  "manufacturer": "",
  "description": "这是一个基于网络套接字的实验室自动化通信组件，用于在主控端与远程实验设备或设备服务之间传递命令、状态和对象数据。它适用于需要集中控制、远程调用和多设备管理的实验室自动化场景。",
  "description_en": "This is a network socket communication component for laboratory automation, used to exchange commands, status information, and serialized objects between a master controller and remote laboratory devices or device services. It is suited for lab automation setups requiring centralized control, remote interaction, and multi-device management.",
  "actions": [
    {
      "action_name": "auto-read",
      "description": "读取来自主控端或远程连接的序列化消息。",
      "description_en": "Read a serialized message from the master controller or remote connection."
    },
    {
      "action_name": "auto-write",
      "description": "向主控端或远程连接发送序列化对象。",
      "description_en": "Send a serialized object to the master controller or remote connection."
    },
    {
      "action_name": "auto-handshake",
      "description": "建立通信握手并确认连接可用。",
      "description_en": "Perform a communication handshake and confirm that the connection is ready."
    },
    {
      "action_name": "auto-listen",
      "description": "监听传入的网络连接或命令请求。",
      "description_en": "Listen for incoming network connections or command requests."
    },
    {
      "action_name": "auto-process_command",
      "description": "处理接收到的远程命令并分发执行。",
      "description_en": "Process a received remote command and dispatch it for execution."
    },
    {
      "action_name": "auto-request_close",
      "description": "请求关闭当前连接或通信会话。",
      "description_en": "Request closure of the current connection or communication session."
    },
    {
      "action_name": "auto-clean_client_threads",
      "description": "清理已结束或无效的客户端线程。",
      "description_en": "Clean up finished or inactive client threads."
    },
    {
      "action_name": "auto-close_client_threads",
      "description": "关闭所有客户端通信线程。",
      "description_en": "Close all client communication threads."
    },
    {
      "action_name": "auto-log",
      "description": "记录通信或运行日志信息。",
      "description_en": "Record communication or runtime log information."
    },
    {
      "action_name": "auto-get_devices_status",
      "description": "获取受管实验设备的状态信息。",
      "description_en": "Get status information for managed laboratory devices."
    },
    {
      "action_name": "auto-get_driver_model",
      "description": "获取通信组件或驱动模型信息。",
      "description_en": "Get communication component or driver model information."
    },
    {
      "action_name": "auto-get_device",
      "description": "获取指定设备对象或设备信息。",
      "description_en": "Get a specified device object or device information."
    },
    {
      "action_name": "auto-get_device_structure",
      "description": "获取设备层级或系统结构信息。",
      "description_en": "Get device hierarchy or system structure information."
    },
    {
      "action_name": "auto-interact",
      "description": "执行交互式远程通信或命令交换。",
      "description_en": "Perform interactive remote communication or command exchange."
    }
  ],
  "tag_hints": [
    "socket communication",
    "remote instrument control",
    "lab automation server",
    "client-server messaging",
    "serialized object transfer",
    "network device management"
  ]
}

